"use client";

import {
  type ButtonHTMLAttributes,
  createContext,
  type HTMLAttributes,
  use,
  useCallback,
  useRef,
  useState,
} from "react";
import { useIndicator } from "../interaction/hooks";
import { cx } from "../utils/cx";

type SegmentedContextValue = { value: string; select: (value: string) => void };
const SegmentedContext = createContext<SegmentedContextValue | null>(null);

export type SegmentedControlProps = Omit<HTMLAttributes<HTMLDivElement>, "onChange" | "defaultValue"> & {
  "aria-label": string;
  /** Controlled selected value. */
  value?: string;
  /** Uncontrolled initial value. */
  defaultValue?: string;
  onValueChange?: (value: string) => void;
};

/**
 * A single-choice set of toggle buttons (`aria-pressed`) for filters and pickers that change a view in place.
 * Not for switching panels: that is `Tabs`, which owns tab panels.
 */
export function SegmentedControl({
  value: controlled,
  defaultValue = "",
  onValueChange,
  className,
  ...rest
}: SegmentedControlProps) {
  const [uncontrolled, setUncontrolled] = useState(defaultValue);
  const value = controlled ?? uncontrolled;
  const ref = useRef<HTMLDivElement>(null);
  useIndicator(ref, { item: ".hm-segment", active: '.hm-segment[aria-pressed="true"]' });
  const select = useCallback(
    (v: string) => {
      if (controlled === undefined) setUncontrolled(v);
      onValueChange?.(v);
    },
    [controlled, onValueChange],
  );
  return (
    <SegmentedContext value={{ value, select }}>
      <div {...rest} ref={ref} role="group" className={cx("hm-segmented", className)} />
    </SegmentedContext>
  );
}

export type SegmentProps = Omit<ButtonHTMLAttributes<HTMLButtonElement>, "value"> & { value: string };

export function Segment({ value, className, onClick, ...rest }: SegmentProps) {
  const ctx = use(SegmentedContext);
  if (!ctx) throw new Error("<Segment> must be inside <SegmentedControl>");
  return (
    <button
      {...rest}
      type="button"
      aria-pressed={ctx.value === value}
      className={cx("hm-segment", className)}
      onClick={(e) => {
        onClick?.(e);
        if (!e.defaultPrevented) ctx.select(value);
      }}
    />
  );
}
